        <section class="ticket-section"><div class="ticket-section__eyebrow">Agenda</div><h2 class="ticket-section__title">Cita y ejecución del servicio</h2><div class="ticket-service-create"><div class="admin-form__group"><label class="admin-form__label" for="appointment_date">Fecha de cita</label><input id="appointment_date" type="date" name="appointment_date" class="admin-form__input" value="<?php echo $escape($values['appointment_date']); ?>"></div><div class="admin-form__group"><label class="admin-form__label" for="appointment_time">Hora de cita</label><input id="appointment_time" type="time" name="appointment_time" class="admin-form__input" value="<?php echo $escape($values['appointment_time']); ?>"></div></div><div class="ticket-service-create"><div class="admin-form__group"><label class="admin-form__label" for="service_date">Fecha de servicio</label><input id="service_date" type="date" name="service_date" class="admin-form__input" value="<?php echo $escape($values['service_date']); ?>"></div><div class="admin-form__row ticket-service-schedule-row"><div class="admin-form__group"><label class="admin-form__label" for="service_start_time">Inicio</label><input id="service_start_time" type="time" name="service_start_time" class="admin-form__input" value="<?php echo $escape($values['service_start_time']); ?>"></div><div class="admin-form__group"><label class="admin-form__label" for="service_end_time">Fin</label><input id="service_end_time" type="time" name="service_end_time" class="admin-form__input" value="<?php echo $escape($values['service_end_time']); ?>"></div></div></div></section>
        <button type="submit" class="btn">Crear ticket</button>
