</section>
<script>const customerMode=document.getElementById('customer_mode'),existingPanel=document.getElementById('existing-customer-panel'),newPanel=document.getElementById('new-customer-panel');document.querySelectorAll('[data-customer-mode]').forEach((button)=>button.addEventListener('click',()=>{const mode=button.dataset.customerMode;customerMode.value=mode;existingPanel.hidden=mode!=='existing';newPanel.hidden=mode!=='new';if(mode==='new')document.getElementById('customer_id').value='';document.querySelectorAll('[data-customer-mode]').forEach((item)=>item.classList.toggle('ticket-customer-mode__option--active',item===button));}));document.querySelectorAll('[data-customer-id]').forEach((button)=>button.addEventListener('click',()=>{document.getElementById('customer_id').value=button.dataset.customerId;document.getElementById('customer_query').value=button.querySelector('.ticket-customer-result__name')?.textContent||'';}));</script>
